"""The real Mailer: Gmail SMTP over SSL (port 465) with an App Password from the Keychain.

* Plain text only. No tracking pixel, no link rewriting, no HTML part.
* The Message-ID is generated by the caller BEFORE the call (`new_message_id`) and stored; the mailer only uses it.
* The connection is opened per message and closed straight after: at 25 emails a day with minutes between them, a
  kept-alive connection would only go stale. The App Password is read from the Keychain when the mailer is made,
  held in a private attribute, and never logged, formatted into an error, or returned.
* Errors are mapped by *how far the SMTP conversation got*, because that decides whether the email may have gone out:

    before DATA is accepted (connect, login, MAIL, RCPT, the DATA command) -> nothing was handed over
        login refused / sender refused (account level)  -> SmtpAuthError       (the whole run stops)
        5xx at RCPT                                     -> RecipientRejected   (this message fails, run continues)
        4xx, drop or timeout                            -> TransientSendError  (stays queued)
    after the message text was sent (waiting for the final reply)
        5xx / 4xx final reply                           -> rejected, definitely not delivered
        drop, timeout, anything else                    -> OutcomeUnknownError (needs_confirmation, never auto-resent)
"""
from __future__ import annotations

import logging
import mimetypes
import re
import smtplib
import ssl
import time
import uuid
from collections.abc import Callable
from email import policy
from email.message import EmailMessage
from email.utils import formataddr, formatdate
from pathlib import Path

from backend.core import config, db, secrets
from backend.core.ports import (MailerError, OutcomeUnknownError, OutgoingEmail, RecipientRejected, SendReceipt,
                                SmtpAuthError, TransientSendError)

log = logging.getLogger("reachout.mailer")
TIMEOUT_S = 30.0
MAX_ATTACHMENT_BYTES = 20 * 1024 * 1024  # Gmail's own limit is 25 MB including encoding overhead


class SendingLimitError(SmtpAuthError):
    """The account (not this recipient) is refused: daily quota reached, sender blocked. Stops the run like a login error."""


def new_message_id(from_addr: str) -> str:
    """A unique RFC 5322 Message-ID in angle brackets, on the sender's own domain."""
    domain = from_addr.rsplit("@", 1)[-1] if "@" in from_addr else "localhost"
    return f"<{uuid.uuid4().hex}.{int(time.time())}@{domain}>"  # os.urandom based: unique even if `random` is seeded


def _one_line(value: str) -> str:
    return " ".join(value.split())  # header values can never carry a line break


def build_message(email: OutgoingEmail) -> EmailMessage:
    msg = EmailMessage(policy=policy.SMTP)
    msg["From"] = formataddr((_one_line(email.from_name), email.from_addr)) if email.from_name.strip() else email.from_addr
    msg["To"] = email.to_addr
    msg["Subject"] = _one_line(email.subject)
    msg["Date"] = formatdate(localtime=True)
    msg["Message-ID"] = email.message_id
    if email.in_reply_to:
        msg["In-Reply-To"] = email.in_reply_to
    if email.references:
        msg["References"] = " ".join(email.references)
    msg.set_content(email.body)  # text/plain only
    if email.attachment_path:
        path = Path(email.attachment_path).expanduser()
        try:
            size = path.stat().st_size
            if size > MAX_ATTACHMENT_BYTES:
                raise MailerError(f"The attachment {path.name} is larger than 20 MB.")
            data = path.read_bytes()
        except OSError as e:
            raise MailerError(f"The attachment {path.name} cannot be read ({e.strerror or 'error'}).") from e
        ctype = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        maintype, _, subtype = ctype.partition("/")
        msg.add_attachment(data, maintype=maintype, subtype=subtype, filename=path.name)
    return msg


def _is_quota(text_: str) -> bool:
    t = text_.lower()
    return any(k in t for k in ("5.4.5", "quota", "limit exceeded", "sending limit", "too many messages"))


def _reply_text(resp: bytes | str) -> str:
    return resp.decode("utf-8", "replace") if isinstance(resp, bytes) else str(resp)


class SmtpMailer:
    def __init__(self, address: str, password: str, host: str = config.SMTP_HOST, port: int = config.SMTP_PORT,
                 timeout: float = TIMEOUT_S, smtp_factory: Callable[[], smtplib.SMTP] | None = None) -> None:
        self.address = address.strip()
        self._password = password
        self.host, self.port, self.timeout = host, port, timeout
        self._factory = smtp_factory or self._ssl_connection  # tests inject a loopback connection

    def __repr__(self) -> str:  # never let the password into a log line or a traceback
        return f"SmtpMailer(address={self.address!r}, host={self.host!r})"

    @classmethod
    def from_settings(cls, engine=None) -> "SmtpMailer":
        address = db.load_settings(engine).gmail_address.strip()
        password = secrets.get_app_password(address) if address else None
        if not address or not password:
            raise SmtpAuthError("Gmail is not set up: add your address and App Password in Settings.")
        return cls(address, password)

    def _ssl_connection(self) -> smtplib.SMTP:
        return smtplib.SMTP_SSL(self.host, self.port, timeout=self.timeout, context=ssl.create_default_context())

    # ------------------------------------------------------------------ connection
    def _open(self) -> smtplib.SMTP:
        """Connect and log in. Everything raised here means nothing was handed over."""
        try:
            s = self._factory()
        except (OSError, smtplib.SMTPException) as e:
            raise TransientSendError(f"Could not connect to {self.host}: {type(e).__name__}") from e
        try:
            s.ehlo()
            s.login(self.address, self._password)
        except smtplib.SMTPAuthenticationError as e:
            self._quit(s)
            raise SmtpAuthError("Gmail rejected the login. Use a 16-character App Password (needs 2-Step Verification), not your normal password.") from e
        except smtplib.SMTPNotSupportedError as e:
            self._quit(s)
            raise SmtpAuthError("The mail server does not offer login on this connection.") from e
        except (OSError, smtplib.SMTPException) as e:
            self._quit(s)
            raise TransientSendError(f"The login did not complete: {type(e).__name__}") from e
        return s

    @staticmethod
    def _quit(s: smtplib.SMTP) -> None:
        try:
            s.quit()
        except Exception:  # noqa: BLE001 - closing a dead connection must never raise
            try:
                s.close()
            except Exception:  # noqa: BLE001
                pass

    def check_login(self) -> None:
        self._quit(self._open())

    def close(self) -> None:  # connections are per message; nothing is held
        return None

    # ------------------------------------------------------------------ send
    def send(self, email: OutgoingEmail) -> SendReceipt:
        data = build_message(email).as_bytes()  # raises MailerError for an unreadable attachment, before any connection
        s = self._open()
        try:
            try:
                code, resp = s.mail(email.from_addr)
                if code != 250:
                    self._raise_before_data(code, resp, "sender")
                code, resp = s.rcpt(email.to_addr)
                if code not in (250, 251):
                    self._raise_before_data(code, resp, "recipient")
                s.putcmd("DATA")
                code, resp = s.getreply()
                if code != 354:
                    self._raise_before_data(code, resp, "data")
            except MailerError:
                raise
            except (OSError, smtplib.SMTPException) as e:
                raise TransientSendError(f"The connection failed before the message was handed over: {type(e).__name__}") from e
            # From here on the server may have the message: any doubt means "outcome unknown".
            return self._finish_data(s, data)
        finally:
            self._quit(s)

    @staticmethod
    def _wire(data: bytes) -> bytes:
        """CRLF line ends, leading dots doubled, terminated by the lone-dot line."""
        data = data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")
        data = re.sub(rb"(?m)^\.", b"..", data)
        if not data.endswith(b"\n"):
            data += b"\n"
        return data.replace(b"\n", b"\r\n") + b".\r\n"

    def _finish_data(self, s: smtplib.SMTP, data: bytes) -> SendReceipt:
        try:
            s.send(self._wire(data))
            code, resp = s.getreply()
        except (OSError, smtplib.SMTPException) as e:  # includes timeouts and SMTPServerDisconnected
            raise OutcomeUnknownError("The connection dropped after the message was sent; it may or may not have been delivered.") from e
        text_ = _reply_text(resp)
        if code == 250:
            return SendReceipt(f"{code} {text_}"[:300])
        if 500 <= code < 600:
            if _is_quota(text_):
                raise SendingLimitError(f"Gmail refused to send: {code} {text_[:200]}")
            raise RecipientRejected(f"The server rejected the message: {code} {text_[:200]}")
        if 400 <= code < 500:
            raise TransientSendError(f"The server deferred the message: {code} {text_[:200]}")
        raise OutcomeUnknownError(f"Unexpected reply after the message was sent: {code} {text_[:200]}")

    @staticmethod
    def _raise_before_data(code: int, resp: bytes | str, stage: str) -> None:
        text_ = _reply_text(resp)[:200]
        if stage == "recipient" and 500 <= code < 600:
            raise RecipientRejected(f"The server refused this recipient: {code} {text_}")
        if 500 <= code < 600:
            if _is_quota(text_) or stage == "sender":
                raise SendingLimitError(f"Gmail refused to send from this account: {code} {text_}")
            raise RecipientRejected(f"The server refused the message: {code} {text_}")
        raise TransientSendError(f"The server deferred the message ({stage}): {code} {text_}")
